/**
 * stopReason 文案视图。
 *
 * 复用 @astra/web-contract 的 STOP_REASON_MAP（项目既定契约），
 * 并对契约未预注册但真实存在的终止码补充本地说明，
 * 使 timeout / 启动失败 / cancelled 与 candidate 在文案上可区分。
 */

import { classifyStopReason } from "@astra/web-contract";
import type { StopReasonInfo } from "@astra/web-contract";

export interface StopReasonView {
  readonly code: string;
  readonly title: string;
  readonly categoryTitle: string;
  readonly description: string;
  /** 该终止码是否已在契约中预注册。 */
  readonly registered: boolean;
}

const LOCAL_OVERRIDES: Record<
  string,
  { title: string; categoryTitle: string; description: string }
> = {
  CANCELLED: {
    title: "求解被取消",
    categoryTitle: "取消",
    description: "运行在收口前被取消（客户端断连或宿主停止），不视为交付候选。",
  },
  ERROR: {
    title: "运行发生未分类错误",
    categoryTitle: "系统故障",
    description: "运行时报告了未细分的错误终止码。",
  },
  BUDGET_EXCEEDED: {
    title: "求解调用预算已超限",
    categoryTitle: "预算 / 时限",
    description: "模型调用或工作单元超出设定上限，受控收口。",
  },
  MAX_ITER: {
    title: "达到最大迭代轮次",
    categoryTitle: "预算 / 时限",
    description: "达到最大迭代次数后受控收口。",
  },
  SOLVED: {
    title: "引擎自报已解出",
    categoryTitle: "引擎自报（未经形式化验证）",
    description: "引擎自报 SOLVED；本控制台不执行形式化验证，产物仍按待审候选呈现。",
  },
  NO_REVIEW: {
    title: "未启用审修流程，直接交付",
    categoryTitle: "消融交付（无审查）",
    description: "未执行 R2/R4 审查与修复闭环，直接交付当前候选答案（常见于 no_review_repair 消融组）。",
  },
  REVIEW_STOP: {
    title: "审查满足准则后停止交付",
    categoryTitle: "正常交付",
    description: "审查阶段判定候选结果满足终止条件，受控收口并交付候选答案。",
  },
  CONTROL_REJECTED: {
    title: "控制策略门控拒绝交付",
    categoryTitle: "受控拒绝（未交付）",
    description: "控制门控检测到违反运行边界或策略约束，拒绝交付并收口为未解。",
  },
  PACKET_REJECTED: {
    title: "候选包格式或闭合校验被拒",
    categoryTitle: "包校验拒绝",
    description: "候选输出包未通过结构或答案闭合门控，退回处理或收口为未解。",
  },
  CONTEXT_REJECTED: {
    title: "上下文或状态校验被拒",
    categoryTitle: "上下文门控拒绝",
    description: "执行上下文未通过准入检查，受控停止并返回未解状态。",
  },
  STOPPED: {
    title: "引擎执行受控中止",
    categoryTitle: "受控中止",
    description: "执行器依据运行条件触发受控停止，未形成最终交付。",
  },
};

export function describeStopReason(code: string | null | undefined): StopReasonView {
  if (!code || !code.trim()) {
    return {
      code: "MISSING",
      title: "未提供终止原因",
      categoryTitle: "未知状态",
      description: "运行记录未携带 stopReason，前端不推测其结论。",
      registered: false,
    };
  }

  const local = LOCAL_OVERRIDES[code];
  if (local) {
    return { code, ...local, registered: false };
  }

  const info: StopReasonInfo = classifyStopReason(code);
  return {
    code: info.code,
    title: info.title,
    categoryTitle: info.categoryTitle,
    description: info.description,
    registered: info.category !== "OTHER",
  };
}